'use strict';

var react = require('react');

// src/viewer/components/elements/chart3d-interaction-hooks.ts
function useStableChart3DInteraction(interaction) {
  const ref = react.useRef(interaction);
  ref.current = interaction;
  const onSelect = react.useCallback((part) => {
    ref.current?.onSelect?.(part);
  }, []);
  const onValueDragPreview = react.useCallback((part, value) => {
    ref.current?.onValueDragPreview?.(part, value);
  }, []);
  const onValueDragCommit = react.useCallback((part, value) => {
    ref.current?.onValueDragCommit?.(part, value);
  }, []);
  return react.useMemo(
    () => ({ onSelect, onValueDragPreview, onValueDragCommit }),
    [onSelect, onValueDragPreview, onValueDragCommit]
  );
}
function useLatestRef(value) {
  const ref = react.useRef(value);
  ref.current = value;
  return ref;
}

exports.useLatestRef = useLatestRef;
exports.useStableChart3DInteraction = useStableChart3DInteraction;
